#!/usr/bin/env python3

from __future__ import annotations

import os
import sys
import json
import urllib.error
import urllib.request
from pathlib import Path

CHUNK_SIZE = 64 * 1024

def download(url: str, output_path: Path) -> None:
    part_path = output_path.with_suffix(output_path.suffix + ".part")
    meta_path = output_path.with_suffix(output_path.suffix + ".part.meta")

    if output_path.exists():
        with urllib.request.urlopen(urllib.request.Request(url, method='HEAD')) as response:
            if int(response.headers.get('Content-Length', 0)) == output_path.stat().st_size:
                return

    meta = {}
    if meta_path.exists():
        with open(meta_path, 'r') as f:
            meta = json.load(f)

    start_byte = 0
    if part_path.exists():
        start_byte = part_path.stat().st_size

    req = urllib.request.Request(url)
    if start_byte > 0 and 'etag' in meta:
        req.add_header('Range', f'bytes={start_byte}-')
        req.add_header('If-Range', meta['etag'])

    try:
        with urllib.request.urlopen(req) as response:
            etag = response.headers.get('ETag')
            content_length = int(response.headers.get('Content-Length', 0))

            if response.status == 206:
                if etag != meta.get('etag'):
                    start_byte = 0
                    mode = 'wb'
                else:
                    mode = 'ab'
            else:
                start_byte = 0
                mode = 'wb'
                if etag:
                    meta = {'etag': etag}
                    with open(meta_path, 'w') as f:
                        json.dump(meta, f)

            with open(part_path, mode) as out_file:
                bytes_received = 0
                while True:
                    chunk = response.read(CHUNK_SIZE)
                    if not chunk:
                        break
                    out_file.write(chunk)
                    bytes_received += len(chunk)

            if content_length and (start_byte + bytes_received) != content_length:
                raise Exception("Size mismatch")

            os.replace(part_path, output_path)
            if meta_path.exists():
                os.remove(meta_path)

    except urllib.error.HTTPError as e:
        if e.code == 416:
            if part_path.exists() and part_path.stat().st_size > 0:
                os.replace(part_path, output_path)
                if meta_path.exists(): os.remove(meta_path)
                return
        raise e

def main(argv: list[str]) -> int:
    if len(argv) != 3:
        print("usage: fetch-file URL OUTPUT_PATH", file=sys.stderr)
        return 2
    try:
        download(argv[1], Path(argv[2]))
    except Exception as exc:
        print(f"download failed: {exc}", file=sys.stderr)
        return 1
    return 0

if __name__ == "__main__":
    sys.exit(main(sys.argv))
